<?php require_once '../config/auth.php'; require_once '../config/database.php'; require_once '../config/layout.php'; require_role('manager'); $s=$pdo->prepare('SELECT l.*,d.nama_divisi FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi WHERE l.id_divisi=? ORDER BY l.id_lowongan DESC');$s->execute([user()['id_divisi']]);$rows=$s->fetchAll(); page_header('Dashboard Manajer Divisi'); ?><div class="card"><div class="top"><div><p>Kelola kebutuhan tenaga kerja untuk divisi kamu.</p></div><a class="btn" href="ajukan_lowongan.php">+ Ajukan Lowongan</a></div></div><table><tr><th>Posisi</th><th>Kebutuhan</th><th>Status</th><th>Pengajuan</th><th>Deadline</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['judul_lowongan'])?></td><td><?=e($r['jumlah_kebutuhan'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?=e($r['tanggal_pengajuan'])?></td><td><?=e($r['deadline']?:'-')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">Belum ada pengajuan.</td></tr><?php endif;?></table><?php page_footer();
